// What's New (task 846): turn the release rows into HTML for the appbar pop-up. Every text value is escaped.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
const releases = $input.all().map((i) => i.json).filter((r) => r && r.release_id);
let html = '<div class="whats-new">';
if (releases.length === 0) {
  html += '<p>No release notes yet.</p>';
}
for (const r of releases) {
  // Release date is the main header; the release goal sits under it as a smaller subheader (Paul, 2026-11-09).
  const first = releases.indexOf(r) === 0;
  html += `<section class="whats-new-release" style="margin-bottom:18px;${first ? '' : 'border-top:1px solid #d1d5db;padding-top:14px;'}">`
    + `<h2 style="margin:0 0 4px 0;font-size:20px;font-weight:700;">${r.shipped ? 'Released ' + esc(r.shipped) : esc(r.label)}</h2>`
    + `<div class="whats-new-goal" style="margin:0 0 8px 0;font-size:14px;font-weight:600;color:#4b5563;white-space:pre-line;">${esc(r.goal || r.label)}</div>`;
  for (const a of (r.areas || [])) {
    html += `<h4 style="margin:10px 0 4px 0;font-size:15px;">${esc(a.area)}</h4><ul style="margin:0 0 0 18px;padding:0;">`;
    for (const n of (a.notes || [])) html += `<li style="margin-bottom:4px;">${esc(n)}</li>`;
    html += '</ul>';
  }
  html += '</section>';
}
html += '</div>';
return [{ json: { html } }];
